// --- 主脚本 ---
// (模式: Run Once for All Items)

// 1. 获取所有输入项 (例如: 2 Items)
const items = $input.all();

// 2. 遍历每一个 item
for (const item of items) {

  // 3. 检查 "图片链接" 字段是否存在且为字符串
  // (使用 bracket notation 来访问中文键)
  if (item.json && item.json['图片链接'] && typeof item.json['图片链接'] === 'string') {

    try {
      // 4. 解析 "图片链接" 字符串 (它是一个 JSON 数组)
      const imagesArray = JSON.parse(item.json['图片链接']);

      // 5. 提取数组中每个对象的 'url' 属性
      const urls = imagesArray.map(image => image.url);

      // 6. "替换" -> 用提取到的 URL 数组 覆盖 原来的 "图片链接" 字段
      item.json['图片链接'] = urls;

    } catch (error) {
      // 如果 JSON 解析失败
      console.log("Error parsing '图片链接' for item:", item, error);
      // 保留其他字段, 只将该字段设置为空数组
      item.json['图片链接'] = [];
    }

  } else {
    // 如果 item.json['图片链接'] 不存在或格式不正确
    // 保留其他字段, 只将该字段设置为空数组
    item.json['图片链接'] = [];
  }
}

// 8. 返回被修改后的 items 数组 (保留了所有旧字段, 并替换了 "图片链接" 的内容)
return items;
